<?php
declare(strict_types=1);
require_once dirname(__DIR__).'/app/bootstrap.php';
require_role(['owner','admin','operations','finance','redeemer']);
$pdo=Database::connection();
$rows=$pdo->query("SELECT b.id,b.booking_code,b.activity_date,b.activity_time,b.participants,b.total_amount,b.currency,b.booking_status,b.payment_status,b.ticket_status,b.created_at,c.full_name,c.email,p.name package_name,t.ticket_code FROM bookings b JOIN customers c ON c.id=b.customer_id JOIN packages p ON p.id=b.package_id LEFT JOIN tickets t ON t.booking_id=b.id ORDER BY b.created_at DESC LIMIT 250")->fetchAll();
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Bookings | BTA Admin</title><style>:root{--orange:#ff5a1f}*{box-sizing:border-box}body{margin:0;background:#f4f2ed;color:#191919;font:14px/1.5 Arial,sans-serif}.top{background:#151515;color:#fff;padding:18px 24px;display:flex;justify-content:space-between}.top a{color:#fff}.wrap{max-width:1300px;margin:auto;padding:30px 20px}.panel{background:#fff;border:1px solid #e2ded6;border-top:3px solid var(--orange);padding:20px;margin:20px 0}.tablewrap{overflow-x:auto}table{border-collapse:collapse;width:100%}th,td{text-align:left;padding:12px;border-bottom:1px solid #e6e2da;vertical-align:top}th{font-size:10px;letter-spacing:.5px}td{font-size:12px}.muted{color:#777}.status{display:inline-block;background:#eee;padding:4px 7px;border-radius:3px;font-size:10px}.small{font-size:11px;overflow-wrap:anywhere}@media(max-width:700px){.wrap{padding:20px 10px}.panel{padding:12px}}</style></head><body><header class="top"><strong>BALI TARANTULA <span style="color:#ff5a1f">ADMIN</span></strong><a href="index.php">← Dashboard</a></header><main class="wrap"><h1>Bookings</h1><p>Booking records, totals, payment status, and ticket status.</p><section class="panel"><div class="tablewrap"><table><thead><tr><th>BOOKING</th><th>GUEST</th><th>ACTIVITY</th><th>TOTAL</th><th>STATUSES</th><th>TICKET</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><strong><?=e($r['booking_code'])?></strong><div class="muted"><?=e($r['created_at'])?></div></td><td><?=e($r['full_name'])?><div class="small"><?=e($r['email'])?></div></td><td><?=e($r['package_name'])?><div class="muted"><?=e($r['activity_date'])?> <?=e(substr((string)$r['activity_time'],0,5))?></div><div class="muted"><?=(int)$r['participants']?> guests</div></td><td><?=e($r['currency'])?> <?=number_format((float)$r['total_amount'],2)?></td><td><span class="status"><?=e($r['booking_status'])?></span><br><span class="status"><?=e($r['payment_status'])?></span><br><span class="status"><?=e($r['ticket_status'])?></span></td><td class="small"><?=$r['ticket_code']?e($r['ticket_code']):'Not issued'?></td></tr><?php endforeach;?><?php if(!$rows):?><tr><td colspan="6">No bookings yet.</td></tr><?php endif;?></tbody></table></div></section></main></body></html>